const resposta = $input.first()?.json?.data;
const texto = typeof resposta === 'string' ? resposta : String(resposta ?? '');
const linhas = texto.replace(/^\uFEFF/, '').split(/\r?\n/).map(linha => linha.trim()).filter(Boolean);
if (linhas.length < 2) throw new Error('O CSV de investimentos está vazio ou inválido.');

const cabecalhos = linhas.shift().split(',').map(campo => campo.trim());
const obrigatorios = ['perfil', 'produto', 'minimo', 'rentabilidade'];
if (!obrigatorios.every(campo => cabecalhos.includes(campo))) {
  throw new Error('O CSV precisa conter perfil, produto, minimo e rentabilidade.');
}

const investimentos = linhas.map(linha => {
  const valores = linha.split(',').map(campo => campo.trim());
  const item = Object.fromEntries(cabecalhos.map((campo, indice) => [campo, valores[indice] ?? '']));
  const minimo = Number(String(item.minimo).replace(/[^\d.-]/g, ''));
  if (!Number.isFinite(minimo)) throw new Error(`Valor mínimo inválido no CSV: ${item.minimo}`);
  return { perfil: item.perfil, produto: item.produto, minimo, rentabilidade: item.rentabilidade };
});

return [{ json: { investimentos } }];

const entrada = $input.first()?.json ?? {};
const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];
const investimentos = entrada.investimentos ?? [];
if (!Array.isArray(clientes) || clientes.length === 0) throw new Error('O Webhook precisa receber body.clientes como uma lista não vazia.');
if (!Array.isArray(investimentos) || investimentos.length === 0) throw new Error('A lista de investimentos está vazia.');

function saldoComoNumero(valor) {
  const normalizado = String(valor ?? '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.');
  const numero = Number(normalizado);
  if (!Number.isFinite(numero)) throw new Error(`Saldo inválido: ${valor}`);
  return numero;
}
const moeda = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });

const resultados = clientes.map(cliente => {
  const saldoNumero = saldoComoNumero(cliente.saldo);
  const elegiveis = investimentos
    .filter(item => item.perfil === cliente.perfil && Number(item.minimo) <= saldoNumero)
    .sort((a, b) => Number(b.minimo) - Number(a.minimo));
  const escolhido = elegiveis[0] ?? null;
  const recomendacao = escolhido ? {
    perfil: escolhido.perfil,
    produto: escolhido.produto,
    minimo: Number(escolhido.minimo),
    rentabilidade: escolhido.rentabilidade
  } : null;
  const saldoTexto = moeda.format(saldoNumero);
  const nome = cliente.nome ?? 'Cliente';
  const produto = escolhido?.produto ?? 'nenhuma opção do CSV atende ao saldo informado';
  const minimoTexto = escolhido ? moeda.format(Number(escolhido.minimo)) : '';
  const rentabilidade = escolhido?.rentabilidade ?? '';
  const nota = 'Dados fictícios do exercício; isto não é uma recomendação financeira.';
  const mensagens = escolhido ? [
    `Olá ${nome}! Pelo seu perfil ${cliente.perfil}, uma opção elegível no exemplo é ${produto} (mínimo ${minimoTexto}). Seu saldo informado (${saldoTexto}) atende ao mínimo. Rentabilidade indicada no CSV do exercício: ${rentabilidade}. ${nota}`,
    `Olá ${nome}! Para o perfil ${cliente.perfil}, o fluxo encontrou ${produto}, com mínimo de ${minimoTexto}. O saldo usado no teste é ${saldoTexto}; a rentabilidade exibida (${rentabilidade}) vem apenas do CSV didático. ${nota}`,
    `${nome}, indo direto ao ponto: neste teste, ${produto} é a opção elegível selecionada para o perfil ${cliente.perfil}, pois o saldo (${saldoTexto}) atende ao mínimo de ${minimoTexto}. Rentabilidade no CSV: ${rentabilidade}. ${nota}`
  ] : [
    `Olá ${nome}! Não encontramos no CSV do exercício um produto de perfil ${cliente.perfil} com valor mínimo compatível com o saldo informado (${saldoTexto}). ${nota}`,
    `Olá ${nome}! O fluxo não localizou uma opção elegível para o perfil ${cliente.perfil} e o saldo informado (${saldoTexto}). ${nota}`,
    `${nome}, o teste não encontrou produto do perfil ${cliente.perfil} cujo mínimo caiba no saldo de ${saldoTexto}. ${nota}`
  ];

  return {
    nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNumero,
    recomendacao,
    motivo: escolhido ? 'saldo_ok' : 'sem_produto_elegivel',
    mensagens,
    mensagem_escolhida: mensagens[0]
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];
